import sys
import math

# Use math.gcd for Python 3.9+ compatibility or fallback
if sys.version_info >= (3, 9):
    from math import gcd
else:
    from math import gcd as _gcd
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))
    except StopIteration:
        return

    # Count existing 1s
    count_ones = 0
    for x in a:
        if x == 1:
            count_ones += 1

    if count_ones > 0:
        # If there is at least one 1, we just need to convert the rest.
        # Each non-1 element can be converted to 1 in 1 operation if adjacent to a 1.
        # Actually, the strategy is: use the existing 1 to convert neighbors one by one.
        # Number of operations = (n - count_ones).
        # Why? Because once we have a 1, we can pick it and an adjacent x, replace x with gcd(1, x)=1.
        # This propagates the 1 to the whole array.
        print(n - count_ones)
        return

    # If no 1s exist, we need to create a 1 first.
    # We look for the shortest contiguous subarray with GCD equal to 1.
    # Let the length of this subarray be L.
    # To create a 1, we need L-1 operations on that subarray.
    # Once we have one 1, we need (n-1) more operations to convert the rest.
    # Total operations = (L - 1) + (n - 1) = n + L - 2.

    min_len = n + 1

    # Brute force all subarrays since n <= 2000. O(n^2 * log(max_val)) is acceptable.
    for i in range(n):
        current_gcd = a[i]
        for j in range(i, n):
            current_gcd = gcd(current_gcd, a[j])
            if current_gcd == 1:
                length = j - i + 1
                if length < min_len:
                    min_len = length
                # Since extending further won't reduce length, break inner loop?
                # No, we need the shortest starting at i. Once gcd becomes 1, any extension is longer.
                # So we can break.
                break

    if min_len > n:
        print(-1)
    else:
        print(n + min_len - 2)

if __name__ == "__main__":
    solve()
